import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p68_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor conv_transpose3d_k355_cuda(torch::Tensor x, torch::Tensor w);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv_transpose3d_k355", &conv_transpose3d_k355_cuda, "Specialized ConvTranspose3d k=(3,5,5) forward");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Specialized ConvTranspose3d kernel for kernel=(3,5,5), stride=(1,1,1), padding=(0,0,0)
// Weight layout from nn.ConvTranspose3d: [Cin, Cout, kD, kH, kW]
// Input:  [N, Cin, D, H, W]
// Output: [N, Cout, D+kD-1, H+kH-1, W+kW-1] = [N, Cout, D+2, H+4, W+4]

__global__ void conv_transpose3d_k355_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int N, int Cin, int Cout,
    int D, int H, int W,
    int OD, int OH, int OW
) {
    // Each thread computes one output element (n, oc, od, oh, ow)
    const int ow = blockIdx.x * blockDim.x + threadIdx.x;
    const int oh = blockIdx.y * blockDim.y + threadIdx.y;
    const int linear_z = blockIdx.z;

    // Decode linear_z -> (n, oc, od)
    const int od = linear_z % OD;
    const int tmp = linear_z / OD;
    const int oc = tmp % Cout;
    const int n  = tmp / Cout;

    if (ow >= OW || oh >= OH || n >= N) return;

    // kD=3, kH=5, kW=5 hardwired
    float acc = 0.0f;

    // input strides: [N, Cin, D, H, W]
    const int in_stride_n  = Cin * D * H * W;
    const int in_stride_c  = D * H * W;
    const int in_stride_d  = H * W;
    const int in_stride_h  = W;

    // weight strides: [Cin, Cout, 3, 5, 5]
    const int w_stride_ic  = Cout * 3 * 5 * 5;
    const int w_stride_oc  = 3 * 5 * 5;
    const int w_stride_kd  = 5 * 5;
    const int w_stride_kh  = 5;

    const float* in_n = input + n * in_stride_n;

    #pragma unroll
    for (int kd = 0; kd < 3; kd++) {
        int id = od - kd;
        if (id < 0 || id >= D) continue;
        #pragma unroll
        for (int kh = 0; kh < 5; kh++) {
            int ih = oh - kh;
            if (ih < 0 || ih >= H) continue;
            #pragma unroll
            for (int kw = 0; kw < 5; kw++) {
                int iw = ow - kw;
                if (iw < 0 || iw >= W) continue;
                for (int ic = 0; ic < Cin; ic++) {
                    float x_val = in_n[ic * in_stride_c + id * in_stride_d + ih * in_stride_h + iw];
                    float w_val = weight[ic * w_stride_ic + oc * w_stride_oc + kd * w_stride_kd + kh * w_stride_kh + kw];
                    acc += x_val * w_val;
                }
            }
        }
    }

    // Output strides: [N, Cout, OD, OH, OW]
    output[n * (Cout * OD * OH * OW) + oc * (OD * OH * OW) + od * (OH * OW) + oh * OW + ow] = acc;
}

torch::Tensor conv_transpose3d_k355_cuda(torch::Tensor x, torch::Tensor w) {
    TORCH_CHECK(x.is_cuda() && w.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(x.dtype() == torch::kFloat32 && w.dtype() == torch::kFloat32, "inputs must be float32");
    TORCH_CHECK(x.dim() == 5, "input must be 5D");
    TORCH_CHECK(w.dim() == 5, "weight must be 5D");

    x = x.contiguous();
    w = w.contiguous();

    int N   = x.size(0);
    int Cin = x.size(1);
    int D   = x.size(2);
    int H   = x.size(3);
    int W   = x.size(4);
    int Cout = w.size(1);

    // kD=3, kH=5, kW=5
    int OD = D + 2;
    int OH = H + 4;
    int OW = W + 4;

    auto output = torch::zeros({N, Cout, OD, OH, OW}, x.options());

    // Thread block: 16x16 over (ow, oh); grid-z covers (n * Cout * OD)
    dim3 block(16, 16, 1);
    dim3 grid(
        (OW + block.x - 1) / block.x,
        (OH + block.y - 1) / block.y,
        N * Cout * OD
    );

    conv_transpose3d_k355_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        output.data_ptr<float>(),
        N, Cin, Cout,
        D, H, W,
        OD, OH, OW
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Performs a transposed 3D convolution with a square input and an asymmetric kernel.

        Args:
            in_channels (int): Number of channels in the input tensor.
            out_channels (int): Number of channels produced by the convolution.
            kernel_size (tuple): Size of the convolution kernel (kernel_depth, kernel_width, kernel_height), 
                                 where kernel_width == kernel_height.
            stride (tuple, optional): Stride of the convolution. Defaults to (1, 1, 1).
            padding (tuple, optional): Padding applied to the input. Defaults to (0, 0, 0).
            output_padding (tuple, optional): Additional size added to one side of the output shape. Defaults to (0, 0, 0).
            groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
            bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
        """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding,
            output_padding=output_padding, groups=groups, bias=bias
        )
        self._kernel_size = tuple(kernel_size)
        self._stride = tuple(stride)
        self._padding = tuple(padding)
        self._output_padding = tuple(output_padding)
        self._groups = groups
        self._use_bias = bias
        self._fastpath_enabled = (
            tuple(kernel_size) == (3, 5, 5) and
            tuple(stride) == (1, 1, 1) and
            tuple(padding) == (0, 0, 0) and
            tuple(output_padding) == (0, 0, 0) and
            groups == 1 and
            not bias
        )
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Performs the transposed 3D convolution.

                Args:
                    x (torch.Tensor): Input tensor of shape (batch_size, in_channels, depth, width, height).

                Returns:
                    torch.Tensor: Output tensor of shape (batch_size, out_channels, depth_out, width_out, height_out).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if (
            self._fastpath_enabled and
            x.is_cuda and
            x.dtype == torch.float32 and
            x.dim() == 5 and
            x.size(1) == self.conv_transpose3d.in_channels
        ):
            return _stark_get_extension().conv_transpose3d_k355(x, self.conv_transpose3d.weight)
        return self.conv_transpose3d(x)
        # <<<END_IMPROVE>>>

