# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor conv_transpose3d_k355_cuda(torch::Tensor x, torch::Tensor w);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv_transpose3d_k355_cuda", &conv_transpose3d_k355_cuda, "ConvTranspose3d k=(3,5,5) stride=1 pad=0");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Output-stationary kernel: each thread computes one (n, oc, od, oh, ow) output element.
// Kernel size fixed at (3,5,5), stride=1, padding=0, groups=1.
// Weight layout: [Cin, Cout, KD, KH, KW] (PyTorch ConvTranspose3d weight convention).
// Output shape: [N, Cout, D+2, H+4, W+4]
//
// Use __launch_bounds__ to help the compiler keep register count low.
__launch_bounds__(256, 4)
__global__ void conv_transpose3d_k355_kernel(
    const float* __restrict__ input,   // [N, Cin, D, H, W]
    const float* __restrict__ weight,  // [Cin, Cout, 3, 5, 5]
    float* __restrict__ output,        // [N, Cout, OD, OH, OW]
    int N, int Cin, int Cout,
    int D, int H, int W,
    int OD, int OH, int OW
) {
    // Linearize over (N, Cout, OD, OH, OW)
    long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long total = (long long)N * Cout * OD * OH * OW;
    if (idx >= total) return;

    int ow = idx % OW; idx /= OW;
    int oh = idx % OH; idx /= OH;
    int od = idx % OD; idx /= OD;
    int oc = idx % Cout;
    int n  = (int)(idx / Cout);

    float acc = 0.0f;

    // ConvTranspose3d backward-data indexing:
    // output[n,oc,od,oh,ow] += sum_{ic,kd,kh,kw} input[n,ic,id,ih,iw] * weight[ic,oc,kd,kh,kw]
    // where id = od - kd, ih = oh - kh, iw = ow - kw  (for stride=1, pad=0)

    // Strides for input: [N, Cin, D, H, W]
    int in_n  = Cin * D * H * W;
    int in_c  = D * H * W;
    int in_d  = H * W;
    // Strides for weight: [Cin, Cout, 3, 5, 5]
    int w_ic  = Cout * 3 * 5 * 5;
    int w_oc  = 3 * 5 * 5;  // = 75
    int w_kd  = 5 * 5;      // = 25
    int w_kh  = 5;

    const float* inp_n = input + (long long)n * in_n;

    for (int ic = 0; ic < Cin; ic++) {
        const float* inp_nc = inp_n + ic * in_c;
        const float* w_ic_ptr = weight + (long long)ic * w_ic + oc * w_oc;

        // kd loop: small, unroll
        #pragma unroll 3
        for (int kd = 0; kd < 3; kd++) {
            int id = od - kd;
            if (id < 0 || id >= D) continue;
            const float* inp_ncd = inp_nc + id * in_d;
            const float* w_kd_ptr = w_ic_ptr + kd * w_kd;

            // kh loop: small, unroll
            #pragma unroll 5
            for (int kh = 0; kh < 5; kh++) {
                int ih = oh - kh;
                if (ih < 0 || ih >= H) continue;
                const float* inp_ncdh = inp_ncd + ih * W;
                const float* w_kh_ptr = w_kd_ptr + kh * w_kh;

                // kw loop: small, unroll
                #pragma unroll 5
                for (int kw = 0; kw < 5; kw++) {
                    int iw = ow - kw;
                    if (iw < 0 || iw >= W) continue;
                    acc += inp_ncdh[iw] * w_kh_ptr[kw];
                }
            }
        }
    }

    long long out_idx = ((long long)n * Cout + oc) * OD * OH * OW
                      + (long long)od * OH * OW
                      + (long long)oh * OW
                      + ow;
    output[out_idx] = acc;
}

torch::Tensor conv_transpose3d_k355_cuda(torch::Tensor x, torch::Tensor w) {
    TORCH_CHECK(x.is_cuda() && w.is_cuda(), "Tensors must be on CUDA");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");
    TORCH_CHECK(w.is_contiguous(), "Weight must be contiguous");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "Input must be float32");
    TORCH_CHECK(w.scalar_type() == torch::kFloat32, "Weight must be float32");
